#!/bin/sh
# regenerates docs/patches.md (see git history for the one-liner); run from repo root with Git Bash
cd "$(dirname "$0")/.." && { echo "# Patches (generated by scripts/gen-patches.sh from src/BetterThanCastle/Patches; do not hand-edit)"; echo "| file | harmony target |"; echo "|---|---|"; for f in src/BetterThanCastle/Patches/*.cs; do grep -h "\[HarmonyPatch(" "$f" | sed -E 's/^\s*\[HarmonyPatch\((.*)\)\]\s*$/\1/' | while read -r l; do echo "| $(basename $f) | $l |"; done; done; } > docs/patches.md
